package main

import (
	"fmt"
	"strings"
	"time"
)

type ledColor byte

const (
	colorOff ledColor = iota
	colorGreen
	colorRed
	colorOrange
)

type statusInput struct {
	connected  bool
	healthCode int
	active     bool
}

type indicator struct {
	activityHold  time.Duration
	activityUntil time.Time
}

func newIndicator(activityHold time.Duration) *indicator {
	return &indicator{activityHold: activityHold}
}

func (i *indicator) observe(input statusInput, now time.Time) (ledColor, time.Time) {
	if !input.connected {
		i.activityUntil = time.Time{}
		return colorOff, time.Time{}
	}
	if input.healthCode > 0 {
		i.activityUntil = time.Time{}
		return colorRed, time.Time{}
	}
	if input.active {
		until := now.Add(i.activityHold)
		if until.After(i.activityUntil) {
			i.activityUntil = until
		}
		return colorOrange, time.Time{}
	}
	if now.Before(i.activityUntil) {
		return colorOrange, i.activityUntil
	}
	i.activityUntil = time.Time{}
	return colorGreen, time.Time{}
}

func mergeLEDColor(current byte, led string, color ledColor) (byte, error) {
	if color > colorOrange {
		return 0, fmt.Errorf("invalid LED color %d", color)
	}
	switch strings.ToUpper(led) {
	case "A1":
		return current&^byte(0x03) | byte(color), nil
	case "A2":
		return current&^byte(0x0c) | byte(color)<<2, nil
	default:
		return 0, fmt.Errorf("LED must be A1 or A2, got %q", led)
	}
}
